//! Wolfram golden replay: structural analytic references.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `fixtures/structural_golden.wls` under Wolfram Engine 15.0.0) evaluates
//! the Euler column load and the Navier+Mindlin plate center deflection
//! from the study inputs with no shared code. The replay calls the
//! introductory studies, so it pins both the closed forms and the
//! default-study parameters they are documented against.

use serde::Deserialize;
use sonium_sim_structural_mechanics::buckling::BucklingStudy;
use sonium_sim_structural_mechanics::plate::Plate2DStudy;
use std::collections::HashMap;

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Entry {
    value: String,
    exact: String,
}

#[derive(Debug, Deserialize)]
struct Meta {
    engine: String,
    protocol: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    meta: Meta,
    values: HashMap<String, Entry>,
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram structural fixture");
    assert!(
        fixture.meta.engine.contains("Wolfram Engine"),
        "fixture must record its Wolfram provenance"
    );
    assert_eq!(fixture.meta.protocol, "audit-oracle-hermetic-v1");
    fixture
}

#[test]
fn euler_pinned_column_load_matches_wolfram() {
    let fixture = parse_fixture();
    let actual = BucklingStudy::introductory()
        .analytical_euler_load_n()
        .expect("introductory column is valid");
    let expected: f64 = fixture.values["euler_pinned_load_n"].value.parse().unwrap();
    let rel = ((actual - expected) / expected).abs();
    assert!(
        rel < 1e-12,
        "Euler load: Rust {actual} vs Wolfram {expected}"
    );
}

#[test]
fn mindlin_plate_center_deflection_matches_wolfram() {
    let fixture = parse_fixture();
    assert!(
        fixture.values["plate_center_deflection_m"]
            .exact
            .contains("Navier+Mindlin"),
        "plate golden must document the formulation"
    );
    let actual = Plate2DStudy::introductory().analytical_center_deflection_m();
    let expected: f64 = fixture.values["plate_center_deflection_m"]
        .value
        .parse()
        .unwrap();
    let rel = ((actual - expected) / expected).abs();
    assert!(
        rel < 1e-12,
        "plate deflection: Rust {actual} vs Wolfram {expected}"
    );
}
